/**
 * Label — generated by the React Native Reusables CLI (`label`), re-skinned.
 *
 * Deviations from upstream: the text is `font-sans text-sm font-medium` in
 * `prose` (textSecondary), the secondary-text token labels read in on web.
 */
import { cn } from '@/lib/utils';
import * as LabelPrimitive from '@rn-primitives/label';
import { Platform } from 'react-native';

function Label({
  className,
  onPress,
  onLongPress,
  onPressIn,
  onPressOut,
  disabled,
  ...props
}: React.ComponentProps<typeof LabelPrimitive.Text>) {
  return (
    <LabelPrimitive.Root
      className={cn(
        'flex select-none flex-row items-center gap-2',
        Platform.select({
          web: 'cursor-default leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-50 group-data-[disabled=true]:pointer-events-none group-data-[disabled=true]:opacity-50',
        }),
        disabled && 'opacity-50',
      )}
      onPress={onPress}
      onLongPress={onLongPress}
      onPressIn={onPressIn}
      onPressOut={onPressOut}
      disabled={disabled}
    >
      <LabelPrimitive.Text
        className={cn(
          'font-sans text-sm font-medium text-prose',
          Platform.select({ web: 'leading-none' }),
          className,
        )}
        {...props}
      />
    </LabelPrimitive.Root>
  );
}

export { Label };
